const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

jest.mock('electron', () => ({
  app: { getVersion: () => '0.0.0-test' }
}));

jest.mock('../sqlite', () => ({
  getStatements: jest.fn(),
  transaction: jest.fn()
}));

const { createDatabase } = require('@usebruno/sqlite');
const { getStatements, transaction } = require('../sqlite');
const { FileIndex } = require('./file-index');

describe('FileIndex denylist', () => {
  let collectionPath;
  let index;
  let db;

  beforeEach(() => {
    collectionPath = fs.mkdtempSync(path.join(os.tmpdir(), 'bruno-file-index-'));
    const opened = createDatabase(':memory:');
    db = opened.db;
    getStatements.mockReturnValue(opened.statements);
    transaction.mockImplementation((callback) => opened.db._transaction(callback));
    index = new FileIndex();

    fs.mkdirSync(path.join(collectionPath, 'hidden'));
    fs.writeFileSync(path.join(collectionPath, 'hidden', 'request.bru'), 'hidden');
    fs.writeFileSync(path.join(collectionPath, 'visible.bru'), 'visible');
    index.stageParsed(collectionPath, path.join(collectionPath, 'hidden', 'request.bru'), { name: 'Hidden' });
    index.stageParsed(collectionPath, path.join(collectionPath, 'visible.bru'), { name: 'Visible' });
  });

  afterEach(() => {
    db.close();
    fs.rmSync(collectionPath, { recursive: true, force: true, maxRetries: 3, retryDelay: 100 });
  });

  test('does not return denied rows from the cache', () => {
    const entries = index.entries(collectionPath, { denylist: ['hidden'] });

    expect([...entries.keys()]).toEqual(['visible.bru']);
  });

  test('does not return rows denied by a folder entry with a trailing separator', () => {
    const entries = index.entries(collectionPath, { denylist: ['hidden/'] });

    expect([...entries.keys()]).toEqual(['visible.bru']);
  });

  test('does not return a row whose path matches a glob', () => {
    const entries = index.entries(collectionPath, { denylist: ['hidden/**'] });

    expect([...entries.keys()]).toEqual(['visible.bru']);
  });

  test('returns a cached file when only an ancestor directory matches the glob', () => {
    const nestedHidden = path.join(collectionPath, 'nested', 'hidden');
    fs.mkdirSync(nestedHidden, { recursive: true });
    fs.writeFileSync(path.join(nestedHidden, 'request.bru'), 'nested-hidden');
    index.stageParsed(collectionPath, path.join(nestedHidden, 'request.bru'), { name: 'Nested Hidden' });

    const entries = index.entries(collectionPath, { denylist: ['**/hidden'] });

    expect([...entries.keys()].sort()).toEqual([
      'visible.bru',
      path.join('hidden', 'request.bru'),
      path.join('nested', 'hidden', 'request.bru')
    ].sort());
  });

  test('does not remove cached rows for a trailing-slash glob', async () => {
    const { removed } = await index.status(collectionPath, { denylist: ['**/'] });
    const removedPaths = removed.map(({ relativePath }) => relativePath);

    expect(removedPaths).not.toContain('visible.bru');
    expect(removedPaths).not.toContain(path.join('hidden', 'request.bru'));
  });

  test('marks previously cached denied rows for removal', async () => {
    const { removed } = await index.status(collectionPath, { denylist: ['hidden'] });

    expect(removed.map(({ relativePath }) => relativePath)).toContain(path.join('hidden', 'request.bru'));
  });

  test('returns denied rows when no denylist is passed', () => {
    const entries = index.entries(collectionPath);

    expect([...entries.keys()].sort()).toEqual([
      path.join('hidden', 'request.bru'),
      'visible.bru'
    ].sort());
  });
});

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

jest.mock('electron', () => ({
  ipcMain: { handle: jest.fn(), on: jest.fn() },
  app: {
    on: jest.fn(),
    getPath: jest.fn(() => require('node:os').tmpdir()),
    getVersion: jest.fn(() => '1.0.0')
  }
}));

jest.mock('../sqlite', () => ({ getStatements: jest.fn(), getFiles: jest.fn(), withSecureDelete: jest.fn((callback) => callback()) }));

const { MAX_RENDERABLE_RESPONSE_BYTES } = require('./index');

const EVENT_DATA = { collectionUid: 'col-1', itemUid: 'item-1' };

const REQUEST_SENT = { method: 'GET', url: 'https://example.com/userinfo', headers: {} };

describe('runner-exchange service', () => {
  let getStatements;
  let getFiles;
  let withSecureDelete;
  let error;

  beforeEach(() => {
    jest.resetModules();
    ({ getStatements, getFiles, withSecureDelete } = require('../sqlite'));
    error = jest.spyOn(console, 'error').mockImplementation(() => {});
  });

  afterEach(() => {
    error.mockRestore();
  });

  const INLINE_MAX = 64;
  let opened;
  let filesDir;
  let readRunnerExchange;
  let storeRunnerExchange;
  let saveRunnerResponseBody;
  let clearRunnerResponses;
  let clearAllRunnerResponses;

  const roundTrip = async ({ requestSent, responseReceived, disableParsingResponseJson }) => {
    if (requestSent) {
      await storeRunnerExchange({ requestUid: 'run-1', eventData: EVENT_DATA, requestSent });
    }
    await storeRunnerExchange({ requestUid: 'run-1', eventData: EVENT_DATA, responseReceived, disableParsingResponseJson });
    return readRunnerExchange('run-1');
  };

  const responseWithBody = (body, headers = { 'content-type': 'application/json' }) => {
    const dataBuffer = Buffer.from(body);
    const { data } = jest.requireActual('../../utils/common').parseDataFromResponse({ data: dataBuffer, headers });
    return { status: 200, statusText: 'OK', headers, duration: 34, size: dataBuffer.length, data, dataBuffer: dataBuffer.toString('base64') };
  };

  beforeEach(() => {
    const { createDatabase } = require('@usebruno/sqlite');
    filesDir = fs.mkdtempSync(path.join(os.tmpdir(), 'bruno-runner-exchange-'));
    opened = createDatabase(':memory:', { filesDir, inlineMaxBytes: INLINE_MAX });
    getStatements.mockReturnValue(opened.statements);
    getFiles.mockReturnValue(opened.files);
    ({ readRunnerExchange, storeRunnerExchange, saveRunnerResponseBody, clearRunnerResponses, clearAllRunnerResponses } = require('./index'));
  });

  afterEach(() => {
    opened.db.close();
    fs.rmSync(filesDir, { recursive: true, force: true, maxRetries: 3, retryDelay: 100 });
  });

  describe('iteration index', () => {
    const storedIterationIndex = (requestUid) =>
      opened.db._db.prepare('SELECT iteration_index FROM runner_responses WHERE request_uid = ?').get(requestUid).iteration_index;

    it('stores the iteration the request ran in', async () => {
      await storeRunnerExchange({ requestUid: 'run-1', eventData: { ...EVENT_DATA, iterationIndex: 2 }, requestSent: REQUEST_SENT });

      expect(storedIterationIndex('run-1')).toBe(2);
    });

    it('stores the first iteration when the run has no iterations', async () => {
      await storeRunnerExchange({ requestUid: 'run-1', eventData: EVENT_DATA, requestSent: REQUEST_SENT });

      expect(storedIterationIndex('run-1')).toBe(0);
    });
  });

  it('returns null when nothing was stored', async () => {
    expect(await readRunnerExchange('missing')).toBeNull();
  });

  it('rebuilds the parsed json body from the stored bytes', async () => {
    const responseReceived = responseWithBody('{"ok":true}');

    const exchange = await roundTrip({ requestSent: REQUEST_SENT, responseReceived });

    expect(exchange.requestSent).toEqual(REQUEST_SENT);
    expect(exchange.responseReceived).toEqual(responseReceived);
    expect(exchange.responseReceived.data).toEqual({ ok: true });
  });

  it('rebuilds a body that spilled to disk', async () => {
    const payload = { items: Array.from({ length: 20 }, (_, i) => ({ id: i })) };
    const responseReceived = responseWithBody(JSON.stringify(payload));

    const exchange = await roundTrip({ responseReceived });

    expect(fs.readdirSync(filesDir).length).toBeGreaterThan(0);
    expect(exchange.responseReceived).toEqual(responseReceived);
    expect(exchange.responseReceived.data).toEqual(payload);
  });

  it('keeps the body a string when json parsing was disabled', async () => {
    const responseReceived = { ...responseWithBody('{"ok":true}'), data: '{"ok":true}' };

    const exchange = await roundTrip({ responseReceived, disableParsingResponseJson: true });

    expect(exchange.responseReceived.data).toBe('{"ok":true}');
  });

  it('decodes the body with the charset from the headers', async () => {
    const headers = { 'content-type': 'text/plain; charset=latin1' };
    const dataBuffer = Buffer.from('caf\u00e9', 'latin1');
    const responseReceived = {
      status: 200,
      headers,
      data: 'caf\u00e9',
      dataBuffer: dataBuffer.toString('base64')
    };

    const exchange = await roundTrip({ responseReceived });

    expect(exchange.responseReceived.data).toBe('caf\u00e9');
    expect(exchange.responseReceived.dataBuffer).toBe(dataBuffer.toString('base64'));
  });

  it('rebuilds an empty body', async () => {
    const responseReceived = { status: 204, statusText: 'No Content', headers: {}, data: '', dataBuffer: '' };

    const exchange = await roundTrip({ responseReceived });

    expect(exchange.responseReceived).toEqual(responseReceived);
  });

  describe('by body size', () => {
    const body = JSON.stringify({ items: Array.from({ length: 20 }, (_, i) => ({ id: i })) });

    const storeWithBodySize = async (size) => {
      await roundTrip({ requestSent: REQUEST_SENT, responseReceived: responseWithBody(body) });
      const { stat } = opened.files;
      jest.spyOn(opened.files, 'stat').mockImplementation((id) => ({ ...stat.call(opened.files, id), size }));
      jest.spyOn(opened.files, 'read');
    };

    it('returns a body that is large but still renderable on demand', async () => {
      await storeWithBodySize(20 * 1024 * 1024);

      const { responseReceived } = await readRunnerExchange('run-1');

      expect(responseReceived.dataBuffer).toBe(Buffer.from(body).toString('base64'));
      expect(responseReceived.data).toEqual(JSON.parse(body));
    });

    it('returns a body right at the renderable limit', async () => {
      await storeWithBodySize(MAX_RENDERABLE_RESPONSE_BYTES);

      expect((await readRunnerExchange('run-1')).responseReceived.dataBuffer).toBe(Buffer.from(body).toString('base64'));
    });
  });

  describe('when the body is over the renderable limit', () => {
    const body = JSON.stringify({ items: Array.from({ length: 20 }, (_, i) => ({ id: i })) });

    beforeEach(async () => {
      await roundTrip({ requestSent: REQUEST_SENT, responseReceived: responseWithBody(body) });
      const { stat } = opened.files;
      jest.spyOn(opened.files, 'stat').mockImplementation((id) => ({ ...stat.call(opened.files, id), size: MAX_RENDERABLE_RESPONSE_BYTES + 1 }));
      jest.spyOn(opened.files, 'read');
    });

    it('returns the metadata without the body', async () => {
      const { responseReceived } = await readRunnerExchange('run-1');

      expect(responseReceived).toMatchObject({ status: 200, statusText: 'OK', size: body.length });
      expect(responseReceived.data).toBeNull();
      expect(responseReceived.dataBuffer).toBeNull();
      expect(responseReceived.storedRequestUid).toBe('run-1');
    });

    it('never reads the body file', async () => {
      const row = opened.statements.execute('get_runner_response', { request_uid: 'run-1' });

      await readRunnerExchange('run-1');

      expect(opened.files.read).not.toHaveBeenCalledWith(row.body_file_id);
    });

    it('still returns the request', async () => {
      expect((await readRunnerExchange('run-1')).requestSent).toEqual(REQUEST_SENT);
    });

    it('still saves the body via the stored request uid', async () => {
      const { responseReceived } = await readRunnerExchange('run-1');
      const destination = path.join(filesDir, 'saved', 'oversize.json');
      fs.mkdirSync(path.dirname(destination));

      await saveRunnerResponseBody(responseReceived.storedRequestUid, destination);

      expect(fs.readFileSync(destination, 'utf8')).toBe(body);
    });
  });

  describe('saving the body to a file', () => {
    let destination;

    beforeEach(() => {
      destination = path.join(filesDir, 'saved', 'response.json');
      fs.mkdirSync(path.dirname(destination));
    });

    it('copies a body that spilled to disk', async () => {
      const body = JSON.stringify({ items: Array.from({ length: 20 }, (_, i) => ({ id: i })) });
      await roundTrip({ responseReceived: responseWithBody(body) });

      await saveRunnerResponseBody('run-1', destination);

      expect(fs.readFileSync(destination, 'utf8')).toBe(body);
    });

    it('writes a body kept inline on the row', async () => {
      await roundTrip({ responseReceived: responseWithBody('{"ok":true}') });

      await saveRunnerResponseBody('run-1', destination);

      expect(fs.readFileSync(destination, 'utf8')).toBe('{"ok":true}');
    });

    it('writes an empty file for an empty body', async () => {
      await roundTrip({ responseReceived: { status: 204, headers: {}, data: '', dataBuffer: '' } });

      await saveRunnerResponseBody('run-1', destination);

      expect(fs.readFileSync(destination, 'utf8')).toBe('');
    });

    it('fails when only the request was stored', async () => {
      await storeRunnerExchange({ requestUid: 'run-1', eventData: EVENT_DATA, requestSent: REQUEST_SENT });

      await expect(saveRunnerResponseBody('run-1', destination)).rejects.toThrow('could not be found');
      expect(fs.existsSync(destination)).toBe(false);
    });

    it('fails when nothing was stored', async () => {
      await expect(saveRunnerResponseBody('missing', destination)).rejects.toThrow('could not be found');
    });
  });

  it('stores the body once rather than again inside the response json', async () => {
    const body = JSON.stringify({ items: Array.from({ length: 20 }, (_, i) => ({ id: i })) });

    await roundTrip({ responseReceived: responseWithBody(body) });

    const row = opened.statements.execute('get_runner_response', { request_uid: 'run-1' });
    const metadata = JSON.parse(Buffer.from(await opened.files.read(row.response_file_id)).toString());
    expect(metadata).not.toHaveProperty('data');
    expect(metadata).not.toHaveProperty('dataBuffer');
  });

  describe('timestamps', () => {
    const timestamps = () => opened.db._db
      .prepare('SELECT created_at, updated_at FROM runner_responses WHERE request_uid = ?')
      .get('run-1');

    it('stamps a new row in epoch seconds', async () => {
      const before = Math.floor(Date.now() / 1000);

      await storeRunnerExchange({ requestUid: 'run-1', eventData: EVENT_DATA, requestSent: REQUEST_SENT });

      const { created_at, updated_at } = timestamps();
      expect(created_at).toBeGreaterThanOrEqual(before);
      expect(updated_at).toBe(created_at);
    });

    it('keeps created_at and refreshes updated_at when the response is written', async () => {
      await storeRunnerExchange({ requestUid: 'run-1', eventData: EVENT_DATA, requestSent: REQUEST_SENT });
      opened.db._db.prepare('UPDATE runner_responses SET created_at = 1, updated_at = 1').run();

      await storeRunnerExchange({ requestUid: 'run-1', eventData: EVENT_DATA, responseReceived: responseWithBody('{"ok":true}') });

      const { created_at, updated_at } = timestamps();
      expect(created_at).toBe(1);
      expect(updated_at).toBeGreaterThan(1);
      expect((await readRunnerExchange('run-1')).requestSent).toEqual(REQUEST_SENT);
    });
  });

  describe('clearing a collection', () => {
    const fileRowCount = () => opened.db._db.prepare('SELECT COUNT(*) AS n FROM files').get().n;

    it('removes the rows and every file they point at', async () => {
      const body = JSON.stringify({ items: Array.from({ length: 20 }, (_, i) => ({ id: i })) });
      await roundTrip({ requestSent: REQUEST_SENT, responseReceived: responseWithBody(body) });
      expect(fileRowCount()).toBe(3);

      await clearRunnerResponses('col-1');

      expect(await readRunnerExchange('run-1')).toBeNull();
      expect(fileRowCount()).toBe(0);
      expect(fs.readdirSync(filesDir)).toHaveLength(0);
    });

    it('clears every collection and its files at once', async () => {
      const body = JSON.stringify({ items: Array.from({ length: 20 }, (_, i) => ({ id: i })) });
      await roundTrip({ requestSent: REQUEST_SENT, responseReceived: responseWithBody(body) });
      await storeRunnerExchange({ requestUid: 'run-2', eventData: { collectionUid: 'col-2' }, responseReceived: responseWithBody('{"other":true}') });

      await clearAllRunnerResponses();

      expect(await readRunnerExchange('run-1')).toBeNull();
      expect(await readRunnerExchange('run-2')).toBeNull();
      expect(fileRowCount()).toBe(0);
      expect(fs.readdirSync(filesDir)).toHaveLength(0);
    });

    it('clears a download-only body file too', async () => {
      const body = JSON.stringify({ items: Array.from({ length: 20 }, (_, i) => ({ id: i })) });
      await roundTrip({ requestSent: REQUEST_SENT, responseReceived: responseWithBody(body) });
      const { stat } = opened.files;
      jest.spyOn(opened.files, 'stat').mockImplementation((id) => ({ ...stat.call(opened.files, id), size: MAX_RENDERABLE_RESPONSE_BYTES + 1 }));

      expect((await readRunnerExchange('run-1')).responseReceived.storedRequestUid).toBe('run-1');

      await clearAllRunnerResponses();

      expect(await readRunnerExchange('run-1')).toBeNull();
      expect(fileRowCount()).toBe(0);
      expect(fs.readdirSync(filesDir)).toHaveLength(0);
    });

    it('deletes the rows and files under secure delete', async () => {
      let rowsDuringScrub;
      withSecureDelete.mockImplementationOnce(async (callback) => {
        await callback();
        rowsDuringScrub = fileRowCount();
      });
      await roundTrip({ requestSent: REQUEST_SENT, responseReceived: responseWithBody('{"ok":true}') });

      await clearAllRunnerResponses();

      expect(rowsDuringScrub).toBe(0);
    });

    it('leaves another collection alone', async () => {
      await roundTrip({ responseReceived: responseWithBody('{"ok":true}') });
      await storeRunnerExchange({ requestUid: 'run-2', eventData: { collectionUid: 'col-2' }, responseReceived: responseWithBody('{"other":true}') });

      await clearRunnerResponses('col-1');

      expect((await readRunnerExchange('run-2')).responseReceived.data).toEqual({ other: true });
    });
  });
});

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

let mockUserData;

jest.mock('electron', () => ({
  app: { getPath: jest.fn(() => mockUserData) }
}));

const SECRET = '[REDACTED]';

describe('sqlite service', () => {
  let sqlite;
  let warn;

  beforeEach(() => {
    jest.resetModules();
    mockUserData = fs.mkdtempSync(path.join(os.tmpdir(), 'bruno-sqlite-service-'));
    warn = jest.spyOn(console, 'warn').mockImplementation(() => {});
    sqlite = require('./index');
    sqlite.openDatabase();
  });

  afterEach(() => {
    sqlite.shutdown();
    warn.mockRestore();
    fs.rmSync(mockUserData, { recursive: true, force: true, maxRetries: 3, retryDelay: 100 });
  });

  const databaseBytes = () =>
    ['bruno.db', 'bruno.db-wal']
      .map((name) => path.join(mockUserData, name))
      .filter((file) => fs.existsSync(file))
      .map((file) => fs.readFileSync(file).toString('latin1'))
      .join('');

  const storeSecret = (secret = SECRET) => sqlite.getFiles().write(JSON.stringify({ headers: { authorization: secret } }));

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  it('leaves deleted bytes on disk without secure delete', async () => {
    const { id } = await storeSecret();

    await sqlite.getFiles().remove(id);

    expect(databaseBytes()).toContain(SECRET);
  });

  it('scrubs deleted bytes from the database and its wal', async () => {
    const { id } = await storeSecret();

    await sqlite.withSecureDelete(() => sqlite.getFiles().remove(id));

    expect(databaseBytes()).not.toContain(SECRET);
    expect(fs.statSync(path.join(mockUserData, 'bruno.db-wal')).size).toBe(0);
  });

  it('keeps secure delete on while another clear is still running', async () => {
    const quick = await storeSecret('Bearer quick-clear-token');
    const slow = await storeSecret('Bearer slow-clear-token');

    await Promise.all([
      sqlite.withSecureDelete(() => sqlite.getFiles().remove(quick.id)),
      sqlite.withSecureDelete(async () => {
        await sleep(20);
        await sqlite.getFiles().remove(slow.id);
      })
    ]);

    expect(databaseBytes()).not.toContain('Bearer quick-clear-token');
    expect(databaseBytes()).not.toContain('Bearer slow-clear-token');
  });

  it('returns what the callback returns', async () => {
    expect(await sqlite.withSecureDelete(() => 42)).toBe(42);
  });

  it('runs the callback when the database is unavailable', async () => {
    sqlite.shutdown();

    expect(await sqlite.withSecureDelete(() => 'ran')).toBe('ran');
  });
});

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

let mockUserDataPath;

jest.mock('electron', () => ({
  app: { getPath: () => mockUserDataPath }
}));

const { TransientManager, transientManager } = require('./index');

describe('TransientManager', () => {
  let manager;

  beforeEach(() => {
    manager = new TransientManager();
    mockUserDataPath = fs.mkdtempSync(path.join(os.tmpdir(), 'bruno-user-data-'));
  });

  afterEach(() => {
    jest.restoreAllMocks();
    fs.rmSync(mockUserDataPath, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
  });

  it('is shared as one instance', () => {
    expect(transientManager).toBeInstanceOf(TransientManager);
  });

  it('lives under tmp/transient/<pid> in the app data directory', () => {
    expect(manager.getRootDirectory()).toBe(path.join(mockUserDataPath, 'tmp', 'transient'));
    expect(manager.getDirectoryBase()).toBe(path.join(mockUserDataPath, 'tmp', 'transient', String(process.pid)));
  });

  describe('clearStale', () => {
    const deadPid = 2147483646;

    beforeEach(() => {
      const realKill = process.kill;
      jest.spyOn(process, 'kill').mockImplementation((pid, signal) => {
        if (pid === deadPid) {
          throw Object.assign(new Error('kill ESRCH'), { code: 'ESRCH' });
        }
        return realKill.call(process, pid, signal);
      });
    });

    it('removes folders left by processes that are no longer running', async () => {
      const stale = path.join(manager.getRootDirectory(), String(deadPid));
      fs.mkdirSync(path.join(stale, 'bruno-abc123'), { recursive: true });
      fs.writeFileSync(path.join(stale, 'bruno-abc123', 'metadata.json'), '{}');
      fs.mkdirSync(path.join(stale, 'bruno-scratch-def456'), { recursive: true });

      await manager.clearStale();

      expect(fs.existsSync(stale)).toBe(false);
    });

    it('removes a folder left under the current process id by an earlier process', async () => {
      const own = manager.getDirectoryBase();
      fs.mkdirSync(path.join(own, 'bruno-abc123'), { recursive: true });

      await manager.clearStale();

      expect(fs.existsSync(own)).toBe(false);
    });

    it('keeps folders of other running instances', async () => {
      const otherPid = 4242;
      process.kill.mockImplementation((pid) => {
        if (pid === otherPid) return true;
        throw Object.assign(new Error('kill ESRCH'), { code: 'ESRCH' });
      });
      const other = path.join(manager.getRootDirectory(), String(otherPid), 'bruno-abc123');
      fs.mkdirSync(other, { recursive: true });

      await manager.clearStale();

      expect(fs.existsSync(other)).toBe(true);
    });

    it('treats a process it is not permitted to signal as running', async () => {
      const otherPid = 4243;
      process.kill.mockImplementation(() => {
        throw Object.assign(new Error('kill EPERM'), { code: 'EPERM' });
      });
      const other = path.join(manager.getRootDirectory(), String(otherPid));
      fs.mkdirSync(other, { recursive: true });

      await manager.clearStale();

      expect(fs.existsSync(other)).toBe(true);
    });

    it('removes folders from the older layout that are not keyed by process id', async () => {
      const legacy = path.join(manager.getRootDirectory(), 'bruno-abc123');
      fs.mkdirSync(legacy, { recursive: true });

      await manager.clearStale();

      expect(fs.existsSync(legacy)).toBe(false);
    });

    it('leaves the rest of the app data directory alone', async () => {
      fs.mkdirSync(manager.getRootDirectory(), { recursive: true });
      fs.writeFileSync(path.join(mockUserDataPath, 'preferences.json'), '{}');

      await manager.clearStale();

      expect(fs.existsSync(path.join(mockUserDataPath, 'preferences.json'))).toBe(true);
    });

    it('does nothing when there is no transient directory', async () => {
      await expect(manager.clearStale()).resolves.toBeUndefined();
    });

    it('does not stop the app from starting when a folder cannot be removed', async () => {
      fs.mkdirSync(path.join(manager.getRootDirectory(), String(deadPid)), { recursive: true });
      jest.spyOn(fs.promises, 'rm').mockRejectedValue(new Error('EBUSY: resource busy or locked'));
      jest.spyOn(console, 'warn').mockImplementation(() => {});

      await expect(manager.clearStale()).resolves.toBeUndefined();
      expect(console.warn).toHaveBeenCalled();
    });
  });
});

