import ThemeProvider from 'providers/Theme/index';
import themes from 'themes/index';
import createExtensions from '../../extensions';
import EditorToolbar from './index';

const mockTheme = themes.light;

// Excluding rawHtmlBlock or rawHtmlTextBlock alone leaves html_block content orphaned since they share a patched renderer.
const createEditor = () => {
  return new Editor({
    extensions: createExtensions().filter((ext) => !['rawHtmlBlock', 'rawHtmlTextBlock'].includes(ext.name)),
    content: '<p>Hello world</p>'
  });
};

const originalResizeObserver = global.ResizeObserver;

// Mock ResizeObserver for EditorToolbar
global.ResizeObserver = class ResizeObserver {
  observe() {}
  unobserve() {}
  disconnect() {}
};

describe('EditorToolbar', () => {
  let editor;
  let offsetWidthSpy;

  beforeAll(() => {
    offsetWidthSpy = jest.spyOn(HTMLElement.prototype, 'offsetWidth', 'get').mockImplementation(function () {
      if (this.className.includes('editor-toolbar')) return 2000;
      return 20;
    });
  });

  afterAll(() => {
    offsetWidthSpy.mockRestore();
    if (originalResizeObserver === undefined) {
      delete global.ResizeObserver;
    } else {
      global.ResizeObserver = originalResizeObserver;
    }
  });

  beforeEach(() => {
    editor = createEditor();
  });

  afterEach(() => {
    editor.destroy();
