import { reconcileSavedChange, findExternallyAddedVariables } from './reconcile';

// Serialized snapshots stand in for the JSON the component compares. The
// concrete strings don't matter; only the equality relationships between
// prevSaved / nextSaved / current do.
const baselineValue = JSON.stringify([{ name: 'token', value: 'a' }]);
const autosavedValue = JSON.stringify([{ name: 'token', value: 'ab' }]);
const userEditedValue = JSON.stringify([{ name: 'token', value: 'abc' }]);
const scriptWrittenValue = JSON.stringify([{ name: 'token', value: 'ax' }]);

describe('reconcileSavedChange', () => {
  it('is a noop when the saved snapshot did not actually change', () => {
    expect(reconcileSavedChange({ prevSaved: baselineValue, nextSaved: baselineValue, current: baselineValue })).toBe('noop');
    // even if the form has drifted, an unchanged save should never touch it
    expect(reconcileSavedChange({ prevSaved: baselineValue, nextSaved: baselineValue, current: userEditedValue })).toBe('noop');
  });

  it('is a noop when the form already matches the incoming snapshot (our own save landing)', () => {
    // user typed 'ab', autosave persisted 'ab', echo comes back == form
    expect(reconcileSavedChange({ prevSaved: baselineValue, nextSaved: autosavedValue, current: autosavedValue })).toBe('noop');
  });

  it('adopts the incoming snapshot when the form is clean (external / file reload)', () => {
    // form still matches the old baseline => no unsaved edits => take new data
    expect(reconcileSavedChange({ prevSaved: baselineValue, nextSaved: autosavedValue, current: baselineValue })).toBe('adopt');
  });

  it('adopts a script-written value when the user is not editing', () => {
    // request script called bru.setEnvVar; form was untouched
    expect(reconcileSavedChange({ prevSaved: baselineValue, nextSaved: scriptWrittenValue, current: baselineValue })).toBe('adopt');
  });

  it('skips (keeps edits) when the user typed ahead during an async save — the data-loss case', () => {
    // autosave persisted 'ab' but the user has since typed 'abc' into the form
    expect(reconcileSavedChange({ prevSaved: baselineValue, nextSaved: autosavedValue, current: userEditedValue })).toBe('skip');
  });

  it('skips a script env update while the user has unsaved edits', () => {
    // script rewrote the value to 'ax' but the user is mid-edit at 'abc'
    expect(reconcileSavedChange({ prevSaved: baselineValue, nextSaved: scriptWrittenValue, current: userEditedValue })).toBe('skip');
  });
});

describe('findExternallyAddedVariables', () => {
  it('finds a variable added purely externally, absent from both baselines', () => {
    const added = findExternallyAddedVariables({
      prevRawSaved: [{ uid: 'u1', name: 'token' }],
      nextRawSaved: [{ uid: 'u1', name: 'token' }, { uid: 'u2', name: 'newVar' }],
      currentValues: [{ uid: 'u1', name: 'token' }, { uid: 'draft', name: '' }]
    });

    expect(added).toEqual([{ uid: 'u2', name: 'newVar' }]);
  });

  it('excludes a name that already existed in the previous saved snapshot (a modification, not an addition)', () => {
    const added = findExternallyAddedVariables({
      prevRawSaved: [{ uid: 'u1', name: 'token' }],
      nextRawSaved: [{ uid: 'u1-new', name: 'token' }],
      currentValues: [{ uid: 'u1', name: 'token' }]
    });

    expect(added).toEqual([]);
  });

  it('excludes a name that collides with something the user is currently editing', () => {
    const added = findExternallyAddedVariables({
      prevRawSaved: [],
      nextRawSaved: [{ uid: 'u2', name: 'newVar' }],
      currentValues: [{ uid: 'u1', name: 'newVar' }, { uid: 'draft', name: '' }]
    });

    expect(added).toEqual([]);
  });

  it('ignores the trailing empty "add new" row when checking for name collisions', () => {
    const added = findExternallyAddedVariables({
      prevRawSaved: [],
      nextRawSaved: [{ uid: 'u2', name: 'newVar' }],
      currentValues: [{ uid: 'draft', name: '' }]
    });

    expect(added).toEqual([{ uid: 'u2', name: 'newVar' }]);
  });

  it('returns an empty array when there is nothing additive', () => {
    const added = findExternallyAddedVariables({
      prevRawSaved: [{ uid: 'u1', name: 'token' }],
      nextRawSaved: [{ uid: 'u1', name: 'token' }],
      currentValues: [{ uid: 'u1', name: 'token' }]
    });

    expect(added).toEqual([]);
  });

  it('handles missing arguments gracefully', () => {
    expect(findExternallyAddedVariables({})).toEqual([]);
  });

  it('excludes a same-uid row even when its name differs — the fast-typing/autosave-echo race', () => {
    const added = findExternallyAddedVariables({
      prevRawSaved: [],
      nextRawSaved: [{ uid: 'u1', name: 'hellll' }],
      currentValues: [{ uid: 'u1', name: 'hellllllloooooo' }, { uid: 'draft', name: '' }]
    });

    expect(added).toEqual([]);
  });

  it('detects a new enabled row added externally even though a disabled row of the same name already existed', () => {
    const added = findExternallyAddedVariables({
      prevRawSaved: [{ uid: 'u1', name: 'token', enabled: false }],
      nextRawSaved: [
        { uid: 'u1', name: 'token', enabled: false },
        { uid: 'u2', name: 'token', enabled: true }
      ],
      currentValues: [{ uid: 'u1', name: 'token', enabled: false }, { uid: 'draft', name: '' }]
    });

    expect(added).toEqual([{ uid: 'u2', name: 'token', enabled: true }]);
  });

  it('detects a new enabled secret added externally even though an enabled plain variable of the same name already existed', () => {
    const added = findExternallyAddedVariables({
      prevRawSaved: [{ uid: 'u1', name: 'token', enabled: true, secret: false }],
      nextRawSaved: [
        { uid: 'u1', name: 'token', enabled: true, secret: false },
        { uid: 'u2', name: 'token', enabled: true, secret: true }
      ],
      currentValues: [{ uid: 'u1', name: 'token', enabled: true, secret: false }, { uid: 'draft', name: '' }]
    });

    expect(added).toEqual([{ uid: 'u2', name: 'token', enabled: true, secret: true }]);
  });
});

import { renderHook } from '@testing-library/react';
import { useReconcileSavedEnvironment } from './useReconcileSavedEnvironment';
import { stripEnvVarUid } from 'utils/environments';

const toSavedJson = (vars) => JSON.stringify(vars.map(stripEnvVarUid));

describe('useReconcileSavedEnvironment', () => {
  it('adopts the incoming snapshot when the form has no unsaved edits', () => {
    const savedA = [{ uid: 'u1', name: 'a', value: '1', type: 'text', enabled: true, secret: false }];
    const formik = {
      values: [{ uid: 'u1', name: 'a', value: '1', type: 'text', enabled: true, secret: false }],
      resetForm: jest.fn(),
      setValues: jest.fn()
    };
    const initialValues = [{ uid: 'new', name: '', value: '', type: 'text', enabled: true, secret: false }];

    const { rerender } = renderHook(
      ({ savedValuesJson, savedVariables }) => useReconcileSavedEnvironment({ formik, savedValuesJson, savedVariables, initialValues }),
      { initialProps: { savedValuesJson: toSavedJson(savedA), savedVariables: savedA } }
    );

    expect(formik.resetForm).not.toHaveBeenCalled();

    // Saved snapshot changes externally (e.g. file reload) while the form still matches the old baseline.
    const savedB = [{ uid: 'u2', name: 'a', value: '2', type: 'text', enabled: true, secret: false }];
    rerender({ savedValuesJson: toSavedJson(savedB), savedVariables: savedB });

    expect(formik.resetForm).toHaveBeenCalledWith({ values: initialValues });
    expect(formik.setValues).not.toHaveBeenCalled();
  });

  it('merges in externally added variables while keeping unsaved edits, without touching the trailing empty row', () => {
    const savedA = [{ uid: 'u1', name: 'a', value: '1', type: 'text', enabled: true, secret: false }];
    const trailingRow = { uid: 'trailing', name: '', value: '', type: 'text', enabled: true, secret: false };
    const formik = {
      // User has an unsaved edit to "a" (value 999) from the very start.
      values: [{ uid: 'u1', name: 'a', value: '999', type: 'text', enabled: true, secret: false }, trailingRow],
      resetForm: jest.fn(),
      setValues: jest.fn()
    };
    const initialValues = [];

    const { rerender } = renderHook(
      ({ savedValuesJson, savedVariables }) => useReconcileSavedEnvironment({ formik, savedValuesJson, savedVariables, initialValues }),
      { initialProps: { savedValuesJson: toSavedJson(savedA), savedVariables: savedA } }
    );

    // A new variable "b" is added externally (e.g. the undefined-variable tooltip's "Add to" switcher)
    // while the form is still dirty from the user's edit to "a".
    const savedB = [
      { uid: 'u1', name: 'a', value: '1', type: 'text', enabled: true, secret: false },
      { uid: 'u2', name: 'b', value: '2', type: 'text', enabled: true, secret: false }
    ];
    rerender({ savedValuesJson: toSavedJson(savedB), savedVariables: savedB });

    expect(formik.resetForm).not.toHaveBeenCalled();
    expect(formik.setValues).toHaveBeenCalledWith([
      { uid: 'u1', name: 'a', value: '999', type: 'text', enabled: true, secret: false },
      { uid: 'u2', name: 'b', value: '2', type: 'text', enabled: true, secret: false, description: '' },
      trailingRow
    ]);
  });

  it('does nothing when the form already matches the incoming snapshot (its own save landing)', () => {
    const savedA = [{ uid: 'u1', name: 'a', value: '1', type: 'text', enabled: true, secret: false }];
    const formik = {
      values: savedA,
      resetForm: jest.fn(),
      setValues: jest.fn()
    };
    const initialValues = [];

    const { rerender } = renderHook(
      ({ savedValuesJson, savedVariables }) => useReconcileSavedEnvironment({ formik, savedValuesJson, savedVariables, initialValues }),
      { initialProps: { savedValuesJson: toSavedJson(savedA), savedVariables: savedA } }
    );

    const savedB = [{ uid: 'u1', name: 'a', value: '2', type: 'text', enabled: true, secret: false }];
    // Simulate the form having already been reset to match the new snapshot (e.g. by handleSave itself).
    formik.values = savedB;
    rerender({ savedValuesJson: toSavedJson(savedB), savedVariables: savedB });

    expect(formik.resetForm).not.toHaveBeenCalled();
    expect(formik.setValues).not.toHaveBeenCalled();
  });
});

'use strict';

const crypto = require('crypto');
const path = require('path');

const IMAGE_EXT_RE = /\.(?:png|jpe?g|gif|svg|webp|avif|ico)(?:\?[^#]*)?(?:#.*)?$/i;

/**
 * @param {string[]|undefined} domains
 * @returns {Set<string>}
 */
function normalizeDomains(domains) {
  return new Set(
    (domains || [])
      .map((d) => String(d).trim().toLowerCase())
      .filter(Boolean)
      .map((d) => d.replace(/^https?:\/\//, '').replace(/\/$/, ''))
  );
}

/**
 * Find http(s) image URLs whose host matches one of the configured domains.
 * @param {string} source
 * @param {string[]} domains
 * @returns {string[]} unique URLs in encounter order
 */
function findRemoteImageUrls(source, domains) {
  const domainSet = normalizeDomains(domains);
  if (!domainSet.size || !source) {
    return [];
  }

  const urlRe = /https?:\/\/[^\s"'`)>\]]+/gi;
  const found = [];
  const seen = new Set();
  let match;
  while ((match = urlRe.exec(source)) !== null) {
    let raw = match[0];
    // Trim common trailing punctuation from markdown/prose
    raw = raw.replace(/[.,;:!?]+$/, '');
    if (!IMAGE_EXT_RE.test(raw)) {
      continue;
    }
    let parsed;
    try {
      parsed = new URL(raw);
    } catch {
      continue;
    }
    const host = parsed.hostname.toLowerCase();
    const hostWithPort = parsed.port ? `${host}:${parsed.port}` : host;
    if (!domainSet.has(host) && !domainSet.has(hostWithPort)) {
      continue;
    }
    if (!seen.has(raw)) {
      seen.add(raw);
      found.push(raw);
    }
  }
  return found;
}

/**
 * Content-addressed asset filename under static/media.
 * @param {string} hash short content hash
 * @param {string} url
 * @returns {string}
 */
function assetFilenameFromHash(hash, url) {
  let ext = '.png';
  try {
    const pathname = new URL(url).pathname;
    const parsedExt = path.extname(pathname);
    if (parsedExt) {
      ext = parsedExt.toLowerCase();
    }
  } catch {
    // keep default
  }
  return `static/media/${hash}${ext}`;
}

/**
 * @param {Buffer|string} content buffer or precomputed hash
 * @param {string} url
 * @returns {string}
 */
function assetFilenameFor(content, url) {
  const hash = typeof content === 'string'
    ? content
    : crypto.createHash('md5').update(content).digest('hex').slice(0, 16);
  return assetFilenameFromHash(hash, url);
}

/**
 * Build a JS module that exports the markdown string with remote image URLs
 * replaced by relative asset paths (e.g. static/media/<hash>.png).
 * Relative paths resolve correctly for both http://localhost and Electron file://.
 *
 * @param {string} source
 * @param {Map<string, string>} urlToAssetPath map of original URL -> emitted asset path
 * @returns {string} JS module source
 */
function buildModuleSource(source, urlToAssetPath) {
  if (!urlToAssetPath.size) {
    return `export default ${JSON.stringify(source)};`;
  }

  let rewritten = source;
  // Replace longest URLs first so overlapping prefixes cannot break substitution
  const urls = [...urlToAssetPath.keys()].sort((a, b) => b.length - a.length);
  for (const url of urls) {
    rewritten = rewritten.split(url).join(urlToAssetPath.get(url));
  }

  return `export default ${JSON.stringify(rewritten)};`;
}

module.exports = {
  IMAGE_EXT_RE,
  normalizeDomains,
  findRemoteImageUrls,
  assetFilenameFor,
  assetFilenameFromHash,
  buildModuleSource
};

import React from 'react';
import { useEffect, useState } from 'react';
import ReactPlayer from 'react-player';

const VideoPreview = React.memo(({ contentType, dataBuffer }) => {
  const [videoUrl, setVideoUrl] = useState(null);

  useEffect(() => {
    const videoType = contentType.split(';')[0];
    const byteArray = Buffer.from(dataBuffer, 'base64');
    const blob = new Blob([byteArray], { type: videoType });
    const url = URL.createObjectURL(blob);
    setVideoUrl(url);
    return () => URL.revokeObjectURL(url);
  }, [contentType, dataBuffer]);

  if (!videoUrl) return <div>Loading video...</div>;

  return (
    <ReactPlayer
      url={videoUrl}
      controls
      muted={true}
      width="100%"
      height="100%"
      onError={(e) => console.error('Error loading video:', e)}
    />
  );
});

export default VideoPreview;

'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { Readable, Transform } = require('stream');
const { pipeline } = require('stream/promises');
const { findRemoteImageUrls, assetFilenameFromHash, buildModuleSource } = require('./utils');

const CACHE_DIR = path.join(process.cwd(), 'node_modules/.cache/bruno-remote-images');

function cachePathsForUrl(url) {
  // Fixed-length key — base64url(url) can exceed Windows MAX_PATH for long URLs.
  const cacheKey = crypto.createHash('sha256').update(url).digest('hex');
  return {
    cacheKey,
    cachePath: path.join(CACHE_DIR, cacheKey),
    hashPath: path.join(CACHE_DIR, `${cacheKey}.hash`)
  };
}

/**
 * Hash a file by streaming it (constant memory).
 * @param {string} filePath
 * @returns {Promise<string>} md5 hex (full)
 */
async function hashFile(filePath) {
  const hash = crypto.createHash('md5');
  for await (const chunk of fs.createReadStream(filePath)) {
    hash.update(chunk);
  }
  return hash.digest('hex');
}

/**
 * Download url to the disk cache via streams. Returns cache path + content hash.
 * Never has the entire file buffer in memory
 *
 * @param {string} url
 * @returns {Promise<{ cachePath: string, hash: string }>}
 */
async function ensureCachedImage(url) {
  const { cachePath, hashPath } = cachePathsForUrl(url);

  try {
    await fs.promises.access(cachePath);
    let hash;
    try {
      hash = (await fs.promises.readFile(hashPath, 'utf8')).trim();
    } catch {
      hash = (await hashFile(cachePath)).slice(0, 16);
      await fs.promises.writeFile(hashPath, hash);
    }
    return { cachePath, hash };
  } catch {
    // cache miss
  }

  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`remote-images: failed to download ${url} (${res.status} ${res.statusText})`);
  }
  if (!res.body) {
    throw new Error(`remote-images: empty body for ${url}`);
  }

  await fs.promises.mkdir(CACHE_DIR, { recursive: true });

  const tmpPath = `${cachePath}.${process.pid}.${crypto.randomBytes(6).toString('hex')}.tmp`;
  const hash = crypto.createHash('md5');

  try {
    await pipeline(
      Readable.fromWeb(res.body),
      new Transform({
        transform(chunk, _enc, cb) {
          hash.update(chunk);
          cb(null, chunk);
        }
      }),
      fs.createWriteStream(tmpPath)
    );

    const shortHash = hash.digest('hex').slice(0, 16);

    try {
      await fs.promises.rename(tmpPath, cachePath);
      await fs.promises.writeFile(hashPath, shortHash);
      return { cachePath, hash: shortHash };
    } catch (err) {
      if (err && (err.code === 'EEXIST' || err.code === 'EPERM')) {
        await fs.promises.rm(tmpPath, { force: true }).catch(() => {});
        let existingHash;
        try {
          existingHash = (await fs.promises.readFile(hashPath, 'utf8')).trim();
        } catch {
          existingHash = (await hashFile(cachePath)).slice(0, 16);
          await fs.promises.writeFile(hashPath, existingHash).catch(() => {});
        }
        return { cachePath, hash: existingHash };
      }
      throw err;
    }
  } catch (err) {
    await fs.promises.rm(tmpPath, { force: true }).catch(() => {});
    throw err;
  }
}

/**
 * rspack emitFile requires string|Buffer — load one cached file at a time.
 * Download path above is fully streamed; this is the unavoidable peak for emit.
 *
 * @param {string} filePath
 * @returns {Promise<Buffer>}
 */
function readCachedFile(filePath) {
  return fs.promises.readFile(filePath);
}

/**
 * Markdown (and other text) loader: download configured-domain image URLs,
 * emit them as rspack assets, rewrite to relative static/media paths.
 *
 * Downloads use Node streams so responses are written straight to disk.
 *
 * @this {import('@rspack/core').LoaderContext}
 * @param {string} source
 */
module.exports = function remoteImagesLoader(source) {
  const callback = this.async();
  const options = this.getOptions() || {};
  const domains = options.domains || [];

  (async () => {
    const urls = findRemoteImageUrls(source, domains);
    if (!urls.length) {
      callback(null, buildModuleSource(source, new Map()));
      return;
    }

    const urlToAssetPath = new Map();
    for (const url of urls) {
      const { cachePath, hash } = await ensureCachedImage(url).catch((err) => {
        console.warn(`remote-images: failed to download ${url} (${err.message})`);
        return { cachePath: null, hash: null };
      });
      if (!cachePath || !hash) {
        continue;
      }
      const filename = assetFilenameFromHash(hash, url);
      // emitFile API needs Buffer; read one file at a time after streaming to disk
      const buffer = await readCachedFile(cachePath);
      this.emitFile(filename, buffer);
      urlToAssetPath.set(url, filename);
      this.addDependency(cachePath);
    }

    callback(null, buildModuleSource(source, urlToAssetPath));
  })().catch((err) => {
    callback(err);
  });
};

module.exports.ensureCachedImage = ensureCachedImage;
module.exports.hashFile = hashFile;
module.exports.CACHE_DIR = CACHE_DIR;
